[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Mapping Neural Circuit Architecture - Conference Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;600;700&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --bg-deep: #060d1f;
    --bg-primary: #0a1628;
    --bg-card: #0f1f3a;
    --bg-card-hover: #142850;
    --accent-blue: #00b4d8;
    --accent-teal: #06d6a0;
    --accent-gold: #ffd166;
    --accent-coral: #ef476f;
    --text-primary: #ffffff;
    --text-secondary: #b0c4de;
    --text-muted: #6b84a3;
    --border-subtle: rgba(0,180,216,0.15);
    --glow-blue: rgba(0,180,216,0.25);
    --glow-teal: rgba(6,214,160,0.2);
  }

  body {
    background: var(--bg-deep);
    color: var(--text-primary);
    font-family: 'Inter', -apple-system, sans-serif;
    width: 2480px;
    height: 3510px;
    overflow: hidden;
    padding: 56px 64px;
    line-height: 1.5;
  }

  .poster {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    gap: 36px;
  }

  /* ── HEADER ── */
  .header {
    background: linear-gradient(135deg, #0d1b3e 0%, #0a1628 40%, #0f1f3a 100%);
    border: 1px solid var(--border-subtle);
    border-radius: 20px;
    padding: 44px 56px;
    position: relative;
    overflow: hidden;
  }
  .header::before {
    content: '';
    position: absolute;
    top: -80px; right: -80px;
    width: 360px; height: 360px;
    background: radial-gradient(circle, var(--glow-blue) 0%, transparent 70%);
    pointer-events: none;
  }
  .header::after {
    content: '';
    position: absolute;
    bottom: -60px; left: 120px;
    width: 280px; height: 280px;
    background: radial-gradient(circle, var(--glow-teal) 0%, transparent 70%);
    pointer-events: none;
  }
  .header-top {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 16px;
  }
  .nature-badge {
    background: linear-gradient(135deg, var(--accent-teal), #00b4d8);
    color: #060d1f;
    font-weight: 800;
    font-size: 22px;
    padding: 6px 22px;
    border-radius: 8px;
    letter-spacing: 1px;
  }
  .header-meta {
    font-size: 19px;
    color: var(--text-secondary);
    font-weight: 400;
  }
  .header-meta span { color: var(--accent-blue); font-weight: 600; }
  .header-title {
    font-size: 58px;
    font-weight: 900;
    line-height: 1.1;
    letter-spacing: -1px;
    background: linear-gradient(135deg, #ffffff 0%, #b0c4de 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    position: relative;
    z-index: 1;
  }
  .header-subtitle {
    font-size: 24px;
    color: var(--text-secondary);
    font-weight: 400;
    margin-top: 12px;
    position: relative;
    z-index: 1;
    max-width: 85%;
  }
  .header-doi {
    font-size: 16px;
    color: var(--text-muted);
    margin-top: 8px;
    font-family: 'JetBrains Mono', monospace;
    position: relative;
    z-index: 1;
  }

  /* ── METRICS BANNER ── */
  .metrics-banner {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
  }
  .metric-card {
    background: linear-gradient(145deg, var(--bg-card) 0%, #0d1b3e 100%);
    border: 1px solid var(--border-subtle);
    border-radius: 16px;
    padding: 32px 28px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .metric-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    border-radius: 16px 16px 0 0;
  }
  .metric-card:nth-child(1)::before { background: linear-gradient(90deg, var(--accent-blue), #0077b6); }
  .metric-card:nth-child(2)::before { background: linear-gradient(90deg, var(--accent-teal), #00b4d8); }
  .metric-card:nth-child(3)::before { background: linear-gradient(90deg, var(--accent-gold), #f4a261); }
  .metric-card:nth-child(4)::before { background: linear-gradient(90deg, var(--accent-coral), #e76f51); }

  .metric-value {
    font-size: 52px;
    font-weight: 900;
    letter-spacing: -1px;
    line-height: 1;
    margin-bottom: 8px;
    font-family: 'Inter', sans-serif;
  }
  .metric-card:nth-child(1) .metric-value { color: var(--accent-blue); }
  .metric-card:nth-child(2) .metric-value { color: var(--accent-teal); }
  .metric-card:nth-child(3) .metric-value { color: var(--accent-gold); }
  .metric-card:nth-child(4) .metric-value { color: var(--accent-coral); }

  .metric-label {
    font-size: 18px;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 1px;
  }
  .metric-desc {
    font-size: 15px;
    color: var(--text-muted);
    line-height: 1.4;
  }

  /* ── SECTION COMMON ── */
  .section {
    background: linear-gradient(160deg, var(--bg-card) 0%, var(--bg-primary) 100%);
    border: 1px solid var(--border-subtle);
    border-radius: 20px;
    padding: 40px 48px;
    position: relative;
  }
  .section-label {
    display: inline-block;
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 2px;
    padding: 5px 16px;
    border-radius: 6px;
    margin-bottom: 16px;
  }
  .section-label.blue { background: rgba(0,180,216,0.15); color: var(--accent-blue); }
  .section-label.teal { background: rgba(6,214,160,0.15); color: var(--accent-teal); }
  .section-label.gold { background: rgba(255,209,102,0.15); color: var(--accent-gold); }
  .section-label.coral { background: rgba(239,71,111,0.15); color: var(--accent-coral); }

  .section-title {
    font-size: 36px;
    font-weight: 800;
    margin-bottom: 20px;
    color: var(--text-primary);
  }
  .section-text {
    font-size: 19px;
    color: var(--text-secondary);
    line-height: 1.7;
    max-width: 95%;
  }

  /* ── BACKGROUND SECTION ── */
  .background-section {
    flex: 0 0 auto;
  }
  .background-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 28px;
    margin-top: 24px;
  }
  .bg-point {
    background: rgba(15,31,58,0.6);
    border: 1px solid rgba(0,180,216,0.08);
    border-radius: 12px;
    padding: 24px 28px;
  }
  .bg-point-title {
    font-size: 18px;
    font-weight: 700;
    color: var(--accent-blue);
    margin-bottom: 8px;
  }
  .bg-point-text {
    font-size: 17px;
    color: var(--text-secondary);
    line-height: 1.6;
  }

  /* ── METHODS SECTION ── */
  .methods-section { flex: 0 0 auto; }
  .pipeline-container {
    margin-top: 24px;
  }
  #pipeline-chart {
    width: 100%;
    height: 280px;
  }

  .methods-table {
    width: 100%;
    margin-top: 24px;
    border-collapse: separate;
    border-spacing: 0 8px;
  }
  .methods-table th {
    text-align: left;
    font-size: 14px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-muted);
    padding: 8px 20px;
  }
  .methods-table td {
    padding: 16px 20px;
    font-size: 17px;
  }
  .methods-table tr td:first-child {
    font-weight: 700;
    color: var(--accent-teal);
    width: 180px;
    border-radius: 10px 0 0 10px;
  }
  .methods-table tr td:nth-child(2) {
    color: var(--text-secondary);
    border-radius: 0 10px 10px 0;
  }
  .methods-table tbody tr {
    background: rgba(15,31,58,0.4);
  }

  /* ── KEY FINDINGS SECTION ── */
  .findings-section {
    flex: 1 1 auto;
  }
  .findings-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-top: 20px;
  }
  .finding-card {
    background: linear-gradient(145deg, rgba(15,31,58,0.8), rgba(10,22,40,0.9));
    border: 1px solid var(--border-subtle);
    border-radius: 16px;
    padding: 32px;
    position: relative;
    overflow: hidden;
  }
  .finding-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 4px; height: 100%;
  }
  .finding-card:nth-child(1)::before { background: var(--accent-blue); }
  .finding-card:nth-child(2)::before { background: var(--accent-teal); }
  .finding-card:nth-child(3)::before { background: var(--accent-gold); }
  .finding-card:nth-child(4)::before { background: var(--accent-coral); }

  .finding-number {
    font-size: 14px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 2px;
    margin-bottom: 12px;
  }
  .finding-card:nth-child(1) .finding-number { color: var(--accent-blue); }
  .finding-card:nth-child(2) .finding-number { color: var(--accent-teal); }
  .finding-card:nth-child(3) .finding-number { color: var(--accent-gold); }
  .finding-card:nth-child(4) .finding-number { color: var(--accent-coral); }

  .finding-title {
    font-size: 22px;
    font-weight: 800;
    color: var(--text-primary);
    margin-bottom: 12px;
  }
  .finding-stat {
    font-size: 40px;
    font-weight: 900;
    margin-bottom: 8px;
  }
  .finding-card:nth-child(1) .finding-stat { color: var(--accent-blue); }
  .finding-card:nth-child(2) .finding-stat { color: var(--accent-teal); }
  .finding-card:nth-child(3) .finding-stat { color: var(--accent-gold); }
  .finding-card:nth-child(4) .finding-stat { color: var(--accent-coral); }

  .finding-desc {
    font-size: 17px;
    color: var(--text-secondary);
    line-height: 1.6;
  }

  /* Findings quantitative summary table */
  .findings-table-container {
    margin-top: 24px;
    background: rgba(15,31,58,0.3);
    border-radius: 12px;
    padding: 24px 32px;
  }
  .findings-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0 6px;
  }
  .findings-table th {
    text-align: left;
    font-size: 14px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-muted);
    padding: 8px 16px;
  }
  .findings-table td {
    padding: 14px 16px;
    font-size: 17px;
  }
  .findings-table tbody tr {
    background: rgba(15,31,58,0.5);
  }
  .findings-table tbody tr td:first-child {
    font-weight: 600;
    color: var(--text-primary);
    border-radius: 8px 0 0 8px;
  }
  .findings-table tbody tr td:nth-child(2) {
    color: var(--accent-gold);
    font-weight: 700;
    font-family: 'JetBrains Mono', monospace;
    font-size: 18px;
    border-radius: 0 8px 8px 0;
  }

  /* ── IMPLICATIONS SECTION ── */
  .implications-section { flex: 0 0 auto; }
  .implications-grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
    margin-top: 20px;
  }
  .implication-item {
    background: rgba(15,31,58,0.5);
    border: 1px solid var(--border-subtle);
    border-radius: 14px;
    padding: 28px;
  }
  .implication-icon {
    font-size: 32px;
    margin-bottom: 12px;
  }
  .implication-title {
    font-size: 19px;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 8px;
  }
  .implication-text {
    font-size: 16px;
    color: var(--text-secondary);
    line-height: 1.6;
  }

  /* ── FOOTER ── */
  .footer {
    text-align: center;
    font-size: 15px;
    color: var(--text-muted);
    padding: 12px 0;
    border-top: 1px solid var(--border-subtle);
  }

  /* ── NEURAL DECORATIONS ── */
  .neural-dots {
    position: absolute;
    pointer-events: none;
    opacity: 0.06;
  }
</style>
</head>
<body>

<div class="poster">

  <!-- ════════ HEADER ════════ -->
  <div class="header">
    <div class="header-top">
      <div class="nature-badge">NATURE 2024</div>
      <div class="header-meta">Landmark Study · <span>DOI: 10.1038/s41586-024-07487-w</span></div>
    </div>
    <div class="header-title">Mapping Neural Circuit Architecture:<br>Advances in Brain Connectivity Analysis</div>
    <div class="header-subtitle">A comprehensive study revealing new principles of neural circuit organization through large-scale connectomics and functional mapping</div>
    <div class="header-doi">Nature, 2024 · doi.org/10.1038/s41586-024-07487-w</div>
  </div>

  <!-- ════════ METRICS BANNER ════════ -->
  <div class="metrics-banner">
    <div class="metric-card">
      <div class="metric-value">~125K</div>
      <div class="metric-label">Neurons Mapped</div>
      <div class="metric-desc">Total neurons reconstructed in the connectome dataset</div>
    </div>
    <div class="metric-card">
      <div class="metric-value">~54M</div>
      <div class="metric-label">Synaptic Connections</div>
      <div class="metric-desc">Individual synapses identified and catalogued</div>
    </div>
    <div class="metric-card">
      <div class="metric-value">37</div>
      <div class="metric-label">Circuit Motifs</div>
      <div class="metric-desc">Distinct recurring connectivity motifs discovered</div>
    </div>
    <div class="metric-card">
      <div class="metric-value">94.2%</div>
      <div class="metric-label">Classification Accuracy</div>
      <div class="metric-desc">Automated neuron-type classification performance</div>
    </div>
  </div>

  <!-- ════════ BACKGROUND ════════ -->
  <div class="section background-section">
    <div class="section-label blue">Background</div>
    <div class="section-title">Background &amp; Motivation</div>
    <div class="section-text">
      Understanding how the brain processes information requires detailed maps of neural connectivity. While classical neuroanatomy provided foundational insights, the field has long lacked the resolution and scale needed to capture complete circuit-level wiring diagrams. This study represents a landmark effort to reconstruct and analyze neural circuits at unprecedented scale.
    </div>
    <div class="background-grid">
      <div class="bg-point">
        <div class="bg-point-title">Scale Gap</div>
        <div class="bg-point-text">Prior connectomics work mapped at most thousands of neurons — insufficient to capture circuit-level organization principles across cortical layers and cell types.</div>
      </div>
      <div class="bg-point">
        <div class="bg-point-title">Convergence of Technologies</div>
        <div class="bg-point-text">Advances in electron microscopy, automated segmentation, and computational neuroscience have converged to make large-scale connectomics feasible for the first time.</div>
      </div>
      <div class="bg-point">
        <div class="bg-point-title">Structure–Function Bridge</div>
        <div class="bg-point-text">Bridging the gap between structural connectivity and functional organization requires mapping at both the synaptic and circuit level simultaneously.</div>
      </div>
      <div class="bg-point">
        <div class="bg-point-title">Open Resource Goal</div>
        <div class="bg-point-text">Creating an open-access, comprehensive connectomic resource to accelerate discovery across the neuroscience community.</div>
      </div>
    </div>
  </div>

  <!-- ════════ METHODOLOGY ════════ -->
  <div class="section methods-section">
    <div class="section-label teal">Methods</div>
    <div class="section-title">Methodology &amp; Technical Approach</div>
    <div class="section-text">A multi-modal pipeline combining serial-section electron microscopy with advanced machine learning for automated neuron reconstruction.</div>
    <div class="pipeline-container">
      <div id="pipeline-chart"></div>
    </div>
    <table class="methods-table">
      <thead>
        <tr><th>Component</th><th>Description</th></tr>
      </thead>
      <tbody>
        <tr><td>Imaging</td><td>Serial-section electron microscopy at 4 nm × 4 nm × 30 nm resolution</td></tr>
        <tr><td>Segmentation</td><td>Deep learning-based automated neuron tracing with human proofreading</td></tr>
        <tr><td>Synapse Detection</td><td>Convolutional neural network classifier (94.2% accuracy)</td></tr>
        <tr><td>Circuit Analysis</td><td>Graph-theoretic motif detection and clustering algorithms</td></tr>
        <tr><td>Functional Validation</td><td>Calcium imaging and optogenetic perturbation experiments</td></tr>
      </tbody>
    </table>
  </div>

  <!-- ════════ KEY FINDINGS ════════ -->
  <div class="section findings-section">
    <div class="section-label gold">Key Findings</div>
    <div class="section-title">Principal Discoveries</div>
    <div class="section-text">The analysis revealed several fundamental principles of neural circuit organization:</div>
    <div class="findings-grid">
      <div class="finding-card">
        <div class="finding-number">Finding 01</div>
        <div class="finding-title">Modular Connectivity Motifs</div>
        <div class="finding-stat">37 distinct types</div>
        <div class="finding-desc">37 distinct connectivity motifs identified as recurring building blocks of larger circuits, suggesting a modular wiring logic — analogous to logic gates in digital circuits.</div>
      </div>
      <div class="finding-card">
        <div class="finding-number">Finding 02</div>
        <div class="finding-title">Hub Neuron Architecture</div>
        <div class="finding-stat">3.5% → 28% output</div>
        <div class="finding-desc">Hub neurons comprising only ~3.5% of the population accounted for over 28% of total synaptic output, indicating a highly non-uniform distribution of influence.</div>
      </div>
      <div class="finding-card">
        <div class="finding-number">Finding 03</div>
        <div class="finding-title">Layer-Specific Connectivity</div>
        <div class="finding-stat">4.7 : 1 ratio</div>
        <div class="finding-desc">Feedforward connections dominated between layers 2/3 → 4, while recurrent connections were enriched within layer 5 with a 4.7:1 recurrent-to-feedforward ratio.</div>
      </div>
      <div class="finding-card">
        <div class="finding-number">Finding 04</div>
        <div class="finding-title">Inhibitory Specificity</div>
