<script src="/app/vendor/infographic.min.js"></script>
<script>
  const pipelineSyntax = `infographic sequence-snake-steps-compact-card
data
  title Connectomics Pipeline
  sequences
    - label Imaging
      desc Serial-section EM at 4nm resolution
    - label Segmentation
      desc Deep learning neuron tracing
    - label Synapse Detection
      desc CNN classifier at 94.2% accuracy
    - label Circuit Analysis
      desc Graph-theoretic motif detection
    - label Validation
      desc Calcium imaging & optogenetics
  order asc
theme
  palette #00b4d8 #06d6a0 #ffd166 #ef476f #a78bfa`;

  const findingsChartSyntax = `infographic chart-bar-plain-text
data
  title Quantitative Findings Summary
  desc Key metrics from the connectome analysis
  values
    - label Motifs
      value 37
    - label Hub Output %
      value 28
    - label Recurrent Ratio
      value 4.7
    - label Inhibitory Specificity
      value 6.2
    - label Classification %
      value 94.2
theme
  palette #00b4d8 #06d6a0 #ffd166 #ef476f #a78bfa`;

  async function renderAll() {
    // Render pipeline infographic
    const pipeline = new AntVInfographic.Infographic({
      container: '#pipeline-chart',
      width: '100%',
      height: '100%',
    });
    await pipeline.render(pipelineSyntax);

    // Render findings chart
    const findingsChart = new AntVInfographic.Infographic({
      container: '#findings-chart',
      width: '100%',
      height: '100%',
    });
    await findingsChart.render(findingsChartSyntax);

    // Wait for fonts
    await document.fonts?.ready;

    // Re-render for font availability
    await pipeline.render(pipelineSyntax);
    await findingsChart.render(findingsChartSyntax);

    // Wait for animations to complete
    await new Promise(r => setTimeout(r, 3000));

    // Signal completion
    window.__posterReady = true;
  }

  renderAll().catch(console.error);
</script>

