node -e "
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 2480, height: 3510 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });

  // Check for console errors
  const errors = [];
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(msg.text());
  });

  // Wait for poster ready
  await page.waitForFunction(() => window.__posterReady === true, { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(2000);

  // Check if infographic containers have SVG content
  const pipelineSVG = await page.evaluate(() => {
    const el = document.querySelector('#pipeline-chart');
    return el ? el.innerHTML.length : 0;
  });
  const findingsSVG = await page.evaluate(() => {
    const el = document.querySelector('#findings-chart');
    return el ? el.innerHTML.length : 0;
  });

  console.log('Pipeline chart SVG length:', pipelineSVG);
  console.log('Findings chart SVG length:', findingsSVG);
  console.log('Console errors:', errors.length ? errors.join('; ') : 'none');

  // Check key sections exist
  const sections = await page.evaluate(() => {
    return {
      header: document.querySelector('.header') !== null,
      metrics: document.querySelector('.metrics-banner') !== null,
      background: document.querySelector('.background-grid') !== null,
      methods: document.querySelector('.methods-table') !== null,
      findings: document.querySelector('.findings-grid') !== null,
      implications: document.querySelector('.implications-grid') !== null,
      footer: document.querySelector('.footer') !== null,
      natureBadge: document.querySelector('.nature-badge')?.textContent || 'missing',
      metricValues: Array.from(document.querySelectorAll('.metric-value')).map(e => e.textContent),
    };
  });
  console.log('Sections present:', JSON.stringify(sections, null, 2));

  await browser.close();
})();
" 2>&1

